type FinanceTab = 'overview' | 'transactions' | 'obligations' | 'accounts' | 'distributions' | 'audit';

const INCOME_CATEGORIES: FinanceCategory[] = ['LicenseSales', 'Sponsorship', 'Donation', 'OtherIncome'];
const EXPENSE_CATEGORIES: FinanceCategory[] = ['Servers', 'Domains', 'ExternalServices', 'SoftwareLicenses', 'Marketing', 'Operational', 'Charitable', 'OtherExpense'];
const ALL_CATEGORIES = [...INCOME_CATEGORIES, ...EXPENSE_CATEGORIES];
const CATEGORY_LABELS: Record<FinanceCategory, string> = {
  LicenseSales: 'Lisans satışları', Sponsorship: 'Sponsorluk', Donation: 'Bağış', OtherIncome: 'Diğer gelir',
  Servers: 'Sunucular', Domains: 'Alan adları', ExternalServices: 'Dış servisler', SoftwareLicenses: 'Yazılım lisansları',
  Marketing: 'Pazarlama', Operational: 'Operasyonel', Charitable: 'Hayır faaliyeti', OtherExpense: 'Diğer gider',
};
const KIND_LABELS: Record<FinanceTransactionKind, string> = {
  OpeningBalance: 'Açılış bakiyesi', Income: 'Gelir', Expense: 'Gider', Transfer: 'Transfer', Distribution: 'Kâr dağıtımı',
};
const PERIOD_LABELS: Record<FinancePeriodSelector, string> = {
  CurrentMonth: 'Bu ay', PreviousMonth: 'Geçen ay', NextMonth: 'Gelecek ay', LastThreeMonths: 'Son 3 ay',
  NextThreeMonths: 'Gelecek 3 ay', Custom: 'Özel aralık',
};

const today = () => new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Istanbul' }).format(new Date());
const money = (value: number) => new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY', minimumFractionDigits: 2 }).format(value);
const percent = (basisPoints: number) => new Intl.NumberFormat('tr-TR', { maximumFractionDigits: 2 }).format(basisPoints / 100);
const date = (value?: string | null) => value ? new Intl.DateTimeFormat('tr-TR', { dateStyle: 'medium', timeZone: 'UTC' }).format(new Date(`${value}T00:00:00Z`)) : '—';
const apiMessage = (error: unknown, fallback: string) => error instanceof ApiError ? error.message : fallback;

function parseMoney(value: string, options: { positive?: boolean } = { positive: true }): number | null {
  const normalized = value.trim().replace(/\s/g, '').replace(',', '.');
  if (!/^-?\d+(?:\.\d{1,2})?$/.test(normalized)) return null;
  const parsed = Number(normalized);
  if (!Number.isFinite(parsed) || (options.positive !== false && parsed <= 0)) return null;
  return parsed;
}

function downloadBlob(blob: Blob, name: string) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url; anchor.download = name; anchor.click();
  URL.revokeObjectURL(url);
}

export function FinanceWorkspace() {
  const [tab, setTab] = useState<FinanceTab>('overview');
  const [holders, setHolders] = useState<FinanceAccountHolderListItem[]>([]);
  const [accounts, setAccounts] = useState<FinanceAccountListItem[]>([]);
  const [referenceLoading, setReferenceLoading] = useState(true);
  const [referenceError, setReferenceError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const loadReference = useCallback(async () => {
    setReferenceLoading(true); setReferenceError(null);
    try {
      const [nextHolders, nextAccounts] = await Promise.all([listFinanceHolders(), listFinanceAccounts()]);
      setHolders(nextHolders); setAccounts(nextAccounts);
    } catch (error) {
      setReferenceError(apiMessage(error, 'Finans hesapları alınamadı.'));
    } finally { setReferenceLoading(false); }
  }, []);

  useEffect(() => { void loadReference(); }, [loadReference]);
  const changed = useCallback(async (message: string) => { setNotice(message); await loadReference(); }, [loadReference]);

  return <div className="finance-workspace">
    <section className="finance-hero">
      <div><span className="eyebrow">Nakit defteri · TRY</span><h2>Finans merkezi</h2><p>Gelir, gider, yükümlülük ve dağıtım kararlarını tek bir denetimli çalışma alanında yönetin.</p></div>
      <div className="finance-hero__facts"><div><strong>{accounts.filter((x) => x.status === 'Active').length}</strong><span>aktif hesap</span></div><div><strong>{holders.filter((x) => x.status === 'Active').length}</strong><span>aktif hesap sahibi</span></div><div><strong>{percent(holders.filter((x) => x.status === 'Active').reduce((sum, x) => sum + x.shareBasisPoints, 0))}%</strong><span>ortak payı</span></div></div>
    </section>
    <Banner tone="info"><strong>Yönetim defteri.</strong> Bu modül nakit ve tahakkuk takibi içindir; mevzuat muhasebesi, vergi veya fatura üretimi sağlamaz.</Banner>
    {notice && <div className="success finance-notice" role="status">{notice}<button type="button" aria-label="Bildirimi kapat" onClick={() => setNotice(null)}>×</button></div>}
    {referenceError && <div className="error" role="alert">{referenceError}<button className="btn btn-secondary btn-sm" type="button" onClick={() => void loadReference()}>Yeniden dene</button></div>}
    <Tabs value={tab} onChange={(value) => setTab(value as FinanceTab)} items={[
      { value: 'overview', label: 'Genel Bakış' }, { value: 'transactions', label: 'İşlemler' },
      { value: 'obligations', label: 'Alacak & Borç' }, { value: 'accounts', label: 'Hesaplar & Ortaklar' },
      { value: 'distributions', label: 'Kâr Dağıtımı' }, { value: 'audit', label: 'Denetim Geçmişi' },
    ]} />
    {tab === 'overview' && <FinanceOverview accounts={accounts} />}
    {tab === 'transactions' && <FinanceTransactions accounts={accounts} holders={holders} disabled={referenceLoading} onChanged={changed} />}
    {tab === 'obligations' && <FinanceObligations accounts={accounts} onChanged={changed} />}
    {tab === 'accounts' && <FinanceAccounts accounts={accounts} holders={holders} loading={referenceLoading} reload={loadReference} onChanged={changed} />}
    {tab === 'distributions' && <FinanceDistributions accounts={accounts} onChanged={changed} />}
    {tab === 'audit' && <FinanceAudit />}
  </div>;
}

function FinanceOverview({ accounts }: { accounts: FinanceAccountListItem[] }) {
  const [period, setPeriod] = useState<FinancePeriodSelector>('CurrentMonth');
  const [startOn, setStartOn] = useState(today()); const [endOn, setEndOn] = useState(today());
  const [accountId, setAccountId] = useState(''); const [months, setMonths] = useState(6);
  const [summary, setSummary] = useState<FinanceSummary | null>(null); const [trend, setTrend] = useState<FinanceTrendPoint[]>([]);
  const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const values = period === 'Custom' ? { period, startOn, endOn, accountId: accountId || undefined } : { period, accountId: accountId || undefined };
      const [nextSummary, nextTrend] = await Promise.all([getFinanceSummary(values), getFinanceTrend(months)]);
      setSummary(nextSummary); setTrend(nextTrend);
    } catch (e) { setError(apiMessage(e, 'Finans özeti alınamadı.')); } finally { setLoading(false); }
  }, [period, startOn, endOn, accountId, months]);
  useEffect(() => { void load(); }, [load]);

  return <section className="finance-panel" role="tabpanel">
    <div className="finance-toolbar">
      <label>Dönem<select className="select-input" value={period} onChange={(e) => setPeriod(e.target.value as FinancePeriodSelector)}>{Object.entries(PERIOD_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
      {period === 'Custom' && <><label>Başlangıç<input className="text-input" type="date" value={startOn} onChange={(e) => setStartOn(e.target.value)} /></label><label>Bitiş<input className="text-input" type="date" value={endOn} onChange={(e) => setEndOn(e.target.value)} /></label></>}
      <label>Hesap<select className="select-input" value={accountId} onChange={(e) => setAccountId(e.target.value)}><option value="">Tüm hesaplar</option>{accounts.map((x) => <option key={x.accountId} value={x.accountId}>{x.holderDisplayName} · {x.name}</option>)}</select></label>
      <label>Trend<select className="select-input" value={months} onChange={(e) => setMonths(Number(e.target.value))}>{[3, 6, 12, 24, 36].map((x) => <option key={x} value={x}>{x} ay</option>)}</select></label>
    </div>
    <LoadState loading={loading} error={error} onRetry={() => void load()} />
    {!loading && summary && <>
      {(summary.periodStartsInFuture || summary.periodIsClosed) && <Banner tone={summary.periodStartsInFuture ? 'warning' : 'neutral'}>{summary.periodStartsInFuture ? 'Seçilen dönem gelecekte başlıyor.' : 'Seçilen dönem sona ermiş; rakamlar dönem sonu görünümüdür.'}</Banner>}
      <div className="finance-kpi-grid finance-kpi-grid--primary">
        <Kpi label="Gelir" value={summary.income} tone="positive" note={`${date(summary.periodStartOn)} – ${date(summary.periodEndOn)}`} />
        <Kpi label="Gider" value={summary.expenses} tone="negative" note="Dönem toplamı" />
        <Kpi label="Net sonuç" value={summary.balance} tone={summary.balance >= 0 ? 'positive' : 'negative'} note="Gelir − gider" />
        <Kpi label="Nakit bakiyesi" value={summary.currentBalance} tone={summary.currentBalance >= 0 ? 'brand' : 'negative'} note={`${date(summary.asOfOn)} itibarıyla`} />
      </div>
      <div className="finance-kpi-grid finance-kpi-grid--secondary">
        <Kpi label="Devreden" value={summary.carriedOver} compact /><Kpi label="Devredecek" value={summary.toBeCarriedOver} compact />
        <Kpi label="Alacak" value={summary.receivables} compact /><Kpi label="Tahsilat" value={summary.collections} compact />
        <Kpi label="Borç" value={summary.debts} compact /><Kpi label="Ödeme" value={summary.payments} compact />
      </div>
      <div className="finance-chart-grid"><TrendChart points={trend} /><CategoryBars summary={summary} /></div>
    </>}
  </section>;
}

function Kpi({ label, value, tone = 'neutral', note, compact = false }: { label: string; value: number; tone?: string; note?: string; compact?: boolean }) {
  return <article className={`finance-kpi finance-kpi--${tone}${compact ? ' finance-kpi--compact' : ''}`}><span>{label}</span><strong>{money(value)}</strong>{note && <small>{note}</small>}</article>;
}

function TrendChart({ points }: { points: FinanceTrendPoint[] }) {
  const max = Math.max(1, ...points.flatMap((x) => [x.income, x.expenses]));
  return <article className="finance-chart-card"><div className="finance-card-head"><div><span className="eyebrow">Nakit akışı</span><h3>Aylık gelir ve gider</h3></div><div className="finance-legend"><span><i className="income" />Gelir</span><span><i className="expense" />Gider</span></div></div>
    {points.length === 0 ? <p className="muted finance-empty">Trend verisi bulunamadı.</p> : <div className="finance-bars" role="img" aria-label={points.map((x) => `${x.month}/${x.year}: gelir ${money(x.income)}, gider ${money(x.expenses)}`).join('; ')}>{points.map((point) => <div className="finance-bars__month" key={`${point.year}-${point.month}`}><div className="finance-bars__columns"><span className="income" style={{ height: `${Math.max(2, point.income / max * 100)}%` }} title={money(point.income)} /><span className="expense" style={{ height: `${Math.max(2, point.expenses / max * 100)}%` }} title={money(point.expenses)} /></div><small>{new Intl.DateTimeFormat('tr-TR', { month: 'short' }).format(new Date(point.year, point.month - 1, 1))}</small></div>)}</div>}
  </article>;
}

function CategoryBars({ summary }: { summary: FinanceSummary }) {
  const max = Math.max(1, ...summary.categoryTotals.map((x) => x.total));
  return <article className="finance-chart-card"><div className="finance-card-head"><div><span className="eyebrow">Dağılım</span><h3>Kategori toplamları</h3></div></div><div className="finance-category-bars">{summary.categoryTotals.length === 0 ? <p className="muted finance-empty">Bu dönemde kategori hareketi yok.</p> : summary.categoryTotals.map((item) => <div key={`${item.kind}-${item.category}`}><div><span>{CATEGORY_LABELS[item.category]}</span><strong>{money(item.total)}</strong></div><span className="finance-category-track"><i className={item.kind === 'Income' ? 'income' : 'expense'} style={{ width: `${item.total / max * 100}%` }} /></span></div>)}</div></article>;
}

function Modal({ title, description, onClose, children, danger = false }: { title: string; description?: string; onClose: () => void; children: ReactNode; danger?: boolean }) {
  const dialog = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  useEffect(() => { onCloseRef.current = onClose; }, [onClose]);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    dialog.current?.querySelector<HTMLElement>('input, select, textarea, button')?.focus();
    const onKey = (event: KeyboardEvent) => { if (event.key === 'Escape') onCloseRef.current(); };
    document.addEventListener('keydown', onKey); return () => { document.removeEventListener('keydown', onKey); previous?.focus(); };
  }, []);
  return <div className="finance-modal-layer"><button className="finance-modal-backdrop" type="button" aria-label="Pencereyi kapat" onClick={onClose} /><div ref={dialog} className={`finance-modal${danger ? ' finance-modal--danger' : ''}`} role="dialog" aria-modal="true" aria-labelledby="finance-modal-title"><div className="finance-modal-head"><div><h2 id="finance-modal-title">{title}</h2>{description && <p>{description}</p>}</div><button className="btn-icon" type="button" onClick={onClose} aria-label="Kapat">×</button></div>{children}</div></div>;
}

function FormActions({ busy, valid, onClose, submit = 'Kaydet', danger = false }: { busy: boolean; valid: boolean; onClose: () => void; submit?: string; danger?: boolean }) {
  return <div className="finance-form-actions"><button className="btn btn-tertiary" type="button" onClick={onClose}>Vazgeç</button><button className={`btn ${danger ? 'btn-danger' : 'btn-primary'}`} type="submit" disabled={busy || !valid}>{busy ? 'İşleniyor…' : submit}</button></div>;
}

function FinanceTransactions({ accounts, holders, disabled, onChanged }: { accounts: FinanceAccountListItem[]; holders: FinanceAccountHolderListItem[]; disabled: boolean; onChanged: (message: string) => Promise<void> }) {
  const [searchInput, setSearchInput] = useState(''); const [search, setSearch] = useState('');
  const [filters, setFilters] = useState<FinanceTransactionFilters>({ page: 1, pageSize: 50 });
  const [data, setData] = useState<PagedResult<FinanceTransactionListItem> | null>(null);
  const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const [formKind, setFormKind] = useState<FinanceTransactionKind | null>(null);
  const [detail, setDetail] = useState<FinanceTransactionDetail | null>(null); const [history, setHistory] = useState<FinanceAuditDetail[]>([]);
  const [detailLoading, setDetailLoading] = useState(false); const [edit, setEdit] = useState(false); const [deleteOpen, setDeleteOpen] = useState(false);
  const [exporting, setExporting] = useState(false);

  useEffect(() => { const timer = window.setTimeout(() => { setSearch(searchInput.trim()); setFilters((x) => ({ ...x, page: 1 })); }, 300); return () => window.clearTimeout(timer); }, [searchInput]);
  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try { setData(await listFinanceTransactions({ ...filters, search: search || undefined })); }
    catch (e) { setError(apiMessage(e, 'Finans işlemleri alınamadı.')); } finally { setLoading(false); }
  }, [filters, search]);
  useEffect(() => { void load(); }, [load]);

  async function openDetail(transactionId: string) {
    setDetailLoading(true); setError(null);
    try {
      const [nextDetail, nextHistory] = await Promise.all([getFinanceTransaction(transactionId), getFinanceTransactionHistory(transactionId)]);
      setDetail(nextDetail); setHistory(nextHistory);
    } catch (e) { setError(apiMessage(e, 'İşlem detayı alınamadı.')); } finally { setDetailLoading(false); }
  }
  async function mutated(message: string, transactionId?: string) {
    setFormKind(null); setEdit(false); setDeleteOpen(false); await load(); await onChanged(message);
    if (transactionId) await openDetail(transactionId); else setDetail(null);
  }
  async function exportCsv() {
    setExporting(true); setError(null);
    try { downloadBlob(await exportFinanceTransactions({ ...filters, search: search || undefined, page: undefined, pageSize: undefined }), 'finance-transactions.csv'); }
    catch (e) { setError(apiMessage(e, 'İşlemler dışa aktarılamadı.')); } finally { setExporting(false); }
  }
  const setFilter = <K extends keyof FinanceTransactionFilters>(key: K, value: FinanceTransactionFilters[K]) => setFilters((x) => ({ ...x, [key]: value || undefined, page: 1 }));

  return <section className="finance-panel" role="tabpanel">
    <div className="finance-section-head"><div><span className="eyebrow">Nakit defteri</span><h2>İşlemler</h2><p>Tüm hareketler türetilmiş hesap bakiyelerine ve değişmez denetim zincirine yansır.</p></div><div className="cluster finance-actions"><button className="btn btn-secondary btn-sm" disabled={disabled} onClick={() => setFormKind('Income')}>+ Gelir</button><button className="btn btn-secondary btn-sm" disabled={disabled} onClick={() => setFormKind('Expense')}>+ Gider</button><button className="btn btn-secondary btn-sm" disabled={disabled} onClick={() => setFormKind('Transfer')}>⇄ Transfer</button><button className="btn btn-tertiary btn-sm" disabled={disabled} onClick={() => setFormKind('OpeningBalance')}>Açılış bakiyesi</button><button className="btn btn-tertiary btn-sm" disabled={exporting} onClick={() => void exportCsv()}>{exporting ? 'Hazırlanıyor…' : 'CSV dışa aktar'}</button></div></div>
    <div className="finance-filter-grid">
      <label>İşlem ara<input className="text-input" value={searchInput} onChange={(e) => setSearchInput(e.target.value)} placeholder="Açıklama, referans, karşı taraf…" /></label>
      <label>Tür<select className="select-input" value={filters.kind ?? ''} onChange={(e) => setFilter('kind', e.target.value as FinanceTransactionKind || undefined)}><option value="">Tüm türler</option>{Object.entries(KIND_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
      <label>Kategori<select className="select-input" value={filters.category ?? ''} onChange={(e) => setFilter('category', e.target.value as FinanceCategory || undefined)}><option value="">Tüm kategoriler</option>{ALL_CATEGORIES.map((x) => <option key={x} value={x}>{CATEGORY_LABELS[x]}</option>)}</select></label>
      <label>Hesap<select className="select-input" value={filters.accountId ?? ''} onChange={(e) => setFilter('accountId', e.target.value || undefined)}><option value="">Tüm hesaplar</option>{accounts.map((x) => <option key={x.accountId} value={x.accountId}>{x.name}</option>)}</select></label>
      <label>Hesap sahibi<select className="select-input" value={filters.holderId ?? ''} onChange={(e) => setFilter('holderId', e.target.value || undefined)}><option value="">Tümü</option>{holders.map((x) => <option key={x.holderId} value={x.holderId}>{x.displayName}</option>)}</select></label>
      <label>Başlangıç<input className="text-input" type="date" value={filters.from ?? ''} onChange={(e) => setFilter('from', e.target.value || undefined)} /></label><label>Bitiş<input className="text-input" type="date" value={filters.to ?? ''} onChange={(e) => setFilter('to', e.target.value || undefined)} /></label>
    </div>
    <LoadState loading={loading || detailLoading} error={error} empty={!loading && data?.items.length === 0} onRetry={() => void load()} />
    {!loading && data && data.items.length > 0 && <><div className="table-wrap"><table className="data-table data-table--stack"><thead><tr><th>Tarih</th><th>Açıklama</th><th>Tür</th><th>Hesap</th><th>Referans</th><th className="num">Tutar</th></tr></thead><tbody>{data.items.map((item) => <tr key={item.transactionId} className="finance-click-row" onClick={() => void openDetail(item.transactionId)}><td data-label="Tarih">{date(item.occurredOn)}</td><td data-label="Açıklama"><strong>{item.description}</strong>{item.counterpartyName && <small>{item.counterpartyName}</small>}</td><td data-label="Tür"><span className={`badge ${item.kind === 'Income' ? 'badge-success' : item.kind === 'Expense' || item.kind === 'Distribution' ? 'badge-danger' : 'badge-neutral'}`}>{KIND_LABELS[item.kind]}</span>{item.category && <small>{CATEGORY_LABELS[item.category]}</small>}</td><td data-label="Hesap">{item.entries.map((x) => x.accountName).join(' → ')}</td><td data-label="Referans" className="mono">{item.reference ?? '—'}</td><td data-label="Tutar" className={`num finance-amount ${item.kind === 'Income' ? 'positive' : item.kind === 'Expense' || item.kind === 'Distribution' ? 'negative' : ''}`}>{money(item.amount)}</td></tr>)}</tbody></table></div><Pager page={data.page} totalPages={data.totalPages} totalCount={data.totalCount} onChange={(page) => setFilters((x) => ({ ...x, page }))} /></>}
    {formKind && <TransactionForm kind={formKind} accounts={accounts} onClose={() => setFormKind(null)} onSaved={(id) => void mutated('İşlem kaydedildi.', id)} />}
    {detail && <DetailDrawer title={detail.transaction.description} subtitle={`${KIND_LABELS[detail.transaction.kind]} · ${date(detail.transaction.occurredOn)}`} onClose={() => setDetail(null)}><TransactionDetailBody detail={detail} history={history} /><div className="finance-drawer-actions">{['Income', 'Expense', 'Transfer'].includes(detail.transaction.kind) && <button className="btn btn-secondary" type="button" onClick={() => setEdit(true)}>İşlemi düzenle</button>}{['Income', 'Expense', 'Transfer'].includes(detail.transaction.kind) && <button className="btn btn-danger-outline" type="button" onClick={() => setDeleteOpen(true)}>İşlemi sil</button>}</div></DetailDrawer>}
    {edit && detail && <TransactionForm kind={detail.transaction.kind} accounts={accounts} detail={detail} onClose={() => setEdit(false)} onSaved={(id) => void mutated('İşlem güncellendi.', id)} onConcurrent={() => void openDetail(detail.transaction.transactionId)} />}
    {deleteOpen && detail && <DeleteTransactionModal detail={detail} onClose={() => setDeleteOpen(false)} onDeleted={() => void mutated('İşlem silindi.')} onConcurrent={() => void openDetail(detail.transaction.transactionId)} />}
  </section>;
}

function TransactionDetailBody({ detail, history }: { detail: FinanceTransactionDetail; history: FinanceAuditDetail[] }) {
  const item = detail.transaction;
  return <div className="stack finance-detail-stack"><DetailBlock title="İşlem"><DetailRow label="Tutar" value={money(item.amount)} /><DetailRow label="Kategori" value={item.category ? CATEGORY_LABELS[item.category] : '—'} /><DetailRow label="Karşı taraf" value={item.counterpartyName ?? '—'} /><DetailRow label="Referans" value={item.reference ?? '—'} /><DetailRow label="Revizyon" value={String(item.revisionNumber)} /></DetailBlock><DetailBlock title="Defter bacakları">{item.entries.map((entry) => <div className="finance-entry" key={`${entry.financeAccountId}-${entry.leg}`}><div><strong>{entry.accountName}</strong><small>{entry.leg}</small></div><span className={entry.amount >= 0 ? 'positive' : 'negative'}>{money(entry.amount)}</span></div>)}</DetailBlock><DetailBlock title="Kayıt"><DetailRow label="Oluşturan" value={detail.createdByEmail} /><DetailRow label="Oluşturma" value={formatDateTime(detail.createdAtUtc)} /><DetailRow label="Son güncelleyen" value={detail.updatedByEmail} /><DetailRow label="Son güncelleme" value={formatDateTime(detail.updatedAtUtc)} /></DetailBlock><DetailBlock title="Denetim zinciri">{history.length === 0 ? <p className="muted">Denetim kaydı yok.</p> : history.map((entry) => <AuditChange key={entry.summary.sequence} detail={entry} />)}</DetailBlock></div>;
}

function TransactionForm({ kind, accounts, detail, onClose, onSaved, onConcurrent }: { kind: FinanceTransactionKind; accounts: FinanceAccountListItem[]; detail?: FinanceTransactionDetail; onClose: () => void; onSaved: (id?: string) => void; onConcurrent?: () => void }) {
  const editable = detail?.transaction; const entry = editable?.entries.find((x) => x.leg === 'Single' || x.leg === 'From'); const toEntry = editable?.entries.find((x) => x.leg === 'To');
  const [currentKind, setCurrentKind] = useState<FinanceTransactionKind>(kind); const [accountId, setAccountId] = useState(entry?.financeAccountId ?? ''); const [toAccountId, setToAccountId] = useState(toEntry?.financeAccountId ?? '');
  const [amountText, setAmountText] = useState(editable ? String(editable.amount) : ''); const [occurredOn, setOccurredOn] = useState(editable?.occurredOn ?? today());
  const [category, setCategory] = useState<FinanceCategory | ''>(editable?.category ?? (kind === 'Income' ? 'LicenseSales' : kind === 'Expense' ? 'Servers' : ''));
  const [description, setDescription] = useState(editable?.description ?? ''); const [reference, setReference] = useState(editable?.reference ?? ''); const [counterparty, setCounterparty] = useState(editable?.counterpartyName ?? ''); const [reason, setReason] = useState('');
  const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  const activeAccounts = accounts.filter((x) => x.status === 'Active'); const amount = parseMoney(amountText, { positive: currentKind !== 'OpeningBalance' });
  const categories = currentKind === 'Income' ? INCOME_CATEGORIES : EXPENSE_CATEGORIES;
  const valid = !!accountId && amount !== null && !!occurredOn && !!description.trim() && (currentKind === 'Income' || currentKind === 'Expense' ? !!category : true) && (currentKind === 'Transfer' ? !!toAccountId && toAccountId !== accountId : true) && (detail ? !!reason.trim() : true);
  useEffect(() => { if ((currentKind === 'Income' || currentKind === 'Expense') && !categories.includes(category as FinanceCategory)) setCategory(categories[0]); }, [currentKind, category, categories]);
  async function submit(event: FormEvent) {
    event.preventDefault(); if (!valid || amount === null) return; setBusy(true); setError(null);
    try {
      let result;
      if (detail) result = await updateFinanceTransaction(detail.transaction.transactionId, { kind: currentKind, category: currentKind === 'Income' || currentKind === 'Expense' ? category as FinanceCategory : null, amount, occurredOn, description: description.trim(), reference: reference.trim() || null, counterpartyName: currentKind === 'Transfer' ? null : counterparty.trim() || null, accountId, toAccountId: currentKind === 'Transfer' ? toAccountId : null, rowVersion: detail.rowVersion, reason: reason.trim() });
      else if (currentKind === 'OpeningBalance') result = await recordFinanceOpeningBalance({ accountId, signedAmount: amount, occurredOn, description: description.trim() });
      else if (currentKind === 'Income') result = await recordFinanceIncome({ accountId, amount, category: category as FinanceCategory, occurredOn, description: description.trim(), reference: reference.trim() || null, counterpartyName: counterparty.trim() || null });
      else if (currentKind === 'Expense') result = await recordFinanceExpense({ accountId, amount, category: category as FinanceCategory, occurredOn, description: description.trim(), reference: reference.trim() || null, counterpartyName: counterparty.trim() || null });
      else result = await recordFinanceTransfer({ fromAccountId: accountId, toAccountId, amount, occurredOn, description: description.trim(), reference: reference.trim() || null });
      onSaved(result.transactionId ?? detail?.transaction.transactionId);
    } catch (e) { if (e instanceof ApiError && e.status === 409 && detail) { setError('İşlem başka biri tarafından değiştirilmiş olabilir. Güncel detay yüklendi; değişiklikleri yeniden gözden geçirin.'); onConcurrent?.(); } else setError(apiMessage(e, 'İşlem kaydedilemedi.')); } finally { setBusy(false); }
  }
  return <Modal title={detail ? 'İşlemi düzenle' : `${KIND_LABELS[currentKind]} kaydet`} description={detail ? 'Değişiklik, önceki ve sonraki haliyle denetim geçmişine yazılır.' : 'Bakiyeler bu kayıttan türetilir; tutarı ve hesabı doğrulayın.'} onClose={onClose}><form onSubmit={(e) => void submit(e)} className="finance-form">{detail && <label>İşlem türü<select className="select-input" value={currentKind} onChange={(e) => setCurrentKind(e.target.value as FinanceTransactionKind)}><option value="Income">Gelir</option><option value="Expense">Gider</option><option value="Transfer">Transfer</option></select></label>}<div className="finance-form-grid"><label>{currentKind === 'Transfer' ? 'Kaynak hesap' : 'Hesap'}<select className="select-input" value={accountId} onChange={(e) => setAccountId(e.target.value)}><option value="">Hesap seçin</option>{activeAccounts.map((x) => <option key={x.accountId} value={x.accountId}>{x.holderDisplayName} · {x.name} ({money(x.currentBalance)})</option>)}</select></label>{currentKind === 'Transfer' && <label>Hedef hesap<select className="select-input" value={toAccountId} onChange={(e) => setToAccountId(e.target.value)}><option value="">Hesap seçin</option>{activeAccounts.filter((x) => x.accountId !== accountId).map((x) => <option key={x.accountId} value={x.accountId}>{x.holderDisplayName} · {x.name}</option>)}</select></label>}<label>Tutar (TRY)<input className="text-input mono" inputMode="decimal" value={amountText} onChange={(e) => setAmountText(e.target.value)} placeholder={currentKind === 'OpeningBalance' ? '-1250,00 veya 1250,00' : '0,00'} aria-invalid={amountText !== '' && amount === null} />{amountText !== '' && amount === null && <small className="field-error">En fazla iki ondalıklı geçerli bir tutar girin.</small>}</label><label>Tarih<input className="text-input" type="date" value={occurredOn} onChange={(e) => setOccurredOn(e.target.value)} /></label></div>{(currentKind === 'Income' || currentKind === 'Expense') && <label>Kategori<select className="select-input" value={category} onChange={(e) => setCategory(e.target.value as FinanceCategory)}>{categories.map((x) => <option key={x} value={x}>{CATEGORY_LABELS[x]}</option>)}</select></label>}<label>Açıklama<input className="text-input" value={description} onChange={(e) => setDescription(e.target.value)} maxLength={300} /></label>{currentKind !== 'OpeningBalance' && <div className="finance-form-grid"><label>Belge / referans<input className="text-input" value={reference} onChange={(e) => setReference(e.target.value)} placeholder="Opsiyonel" /></label>{currentKind !== 'Transfer' && <label>Karşı taraf<input className="text-input" value={counterparty} onChange={(e) => setCounterparty(e.target.value)} placeholder="Opsiyonel" /></label>}</div>}{detail && <label>Değişiklik gerekçesi<textarea className="text-input" value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Zorunlu denetim gerekçesi" /></label>}{error && <div className="error" role="alert">{error}</div>}<FormActions busy={busy} valid={valid} onClose={onClose} submit={detail ? 'Değişiklikleri kaydet' : 'İşlemi kaydet'} /></form></Modal>;
}

function DeleteTransactionModal({ detail, onClose, onDeleted, onConcurrent }: { detail: FinanceTransactionDetail; onClose: () => void; onDeleted: () => void; onConcurrent: () => void }) {
  const [reason, setReason] = useState(''); const [phrase, setPhrase] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { await deleteFinanceTransaction(detail.transaction.transactionId, detail.rowVersion, reason.trim()); onDeleted(); } catch (e) { if (e instanceof ApiError && e.status === 409) { setError('İşlem değişti veya bağlı bir kayıt tarafından korunuyor. Güncel detay yüklendi.'); onConcurrent(); } else setError(apiMessage(e, 'İşlem silinemedi.')); } finally { setBusy(false); } }
  return <Modal danger title="İşlemi kalıcı olarak sil" description={`${money(detail.transaction.amount)} tutarındaki kayıt defterden kaldırılacak; denetim izi korunacak.`} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><Banner tone="danger"><strong>Bu bir hard-delete işlemidir.</strong> Bakiyeler geriye dönük değişir. Bağlı obligation veya dağıtım işlemleri silinemez.</Banner><label>Silme gerekçesi<textarea className="text-input" value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Zorunlu denetim gerekçesi" /></label><label>Onaylamak için <strong>SİL</strong> yazın<input className="text-input mono" value={phrase} onChange={(e) => setPhrase(e.target.value)} /></label>{error && <div className="error" role="alert">{error}</div>}<FormActions busy={busy} valid={!!reason.trim() && phrase === 'SİL'} onClose={onClose} submit="İşlemi sil" danger /></form></Modal>;
}

function FinanceObligations({ accounts, onChanged }: { accounts: FinanceAccountListItem[]; onChanged: (message: string) => Promise<void> }) {
  const [direction, setDirection] = useState<FinanceObligationDirection | ''>(''); const [status, setStatus] = useState<FinanceObligationStatus | ''>(''); const [page, setPage] = useState(1);
  const [data, setData] = useState<PagedResult<FinanceObligationListItem> | null>(null); const [detail, setDetail] = useState<FinanceObligationListItem | null>(null);
  const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null); const [createOpen, setCreateOpen] = useState(false);
  const [action, setAction] = useState<'settle' | 'writeOff' | 'cancel' | null>(null); const [settlementToCancel, setSettlementToCancel] = useState<string | null>(null);
  const load = useCallback(async () => { setLoading(true); setError(null); try { setData(await listFinanceObligations({ direction: direction || undefined, status: status || undefined, page, pageSize: 50 })); } catch (e) { setError(apiMessage(e, 'Alacak ve borçlar alınamadı.')); } finally { setLoading(false); } }, [direction, status, page]);
  useEffect(() => { void load(); }, [load]);
  async function open(id: string) { setError(null); try { setDetail(await getFinanceObligation(id)); } catch (e) { setError(apiMessage(e, 'Kayıt detayı alınamadı.')); } }
  async function mutated(message: string, keepOpen = true) { const id = detail?.obligationId; setCreateOpen(false); setAction(null); setSettlementToCancel(null); await load(); await onChanged(message); if (id && keepOpen) await open(id); else setDetail(null); }
  return <section className="finance-panel" role="tabpanel"><div className="finance-section-head"><div><span className="eyebrow">Tahakkuk katmanı</span><h2>Alacaklar ve borçlar</h2><p>Yükümlülük kaydı nakit yaratmaz; tahsilat veya ödeme ayrı bir defter işlemi oluşturur.</p></div><button className="btn btn-primary" type="button" onClick={() => setCreateOpen(true)}>+ Yeni kayıt</button></div><div className="finance-toolbar"><label>Yön<select className="select-input" value={direction} onChange={(e) => { setDirection(e.target.value as FinanceObligationDirection | ''); setPage(1); }}><option value="">Tümü</option><option value="Receivable">Alacak</option><option value="Payable">Borç</option></select></label><label>Durum<select className="select-input" value={status} onChange={(e) => { setStatus(e.target.value as FinanceObligationStatus | ''); setPage(1); }}><option value="">Tüm durumlar</option>{['Open','PartiallySettled','Settled','WrittenOff','Cancelled'].map((x) => <option key={x} value={x}>{obligationStatusLabel(x as FinanceObligationStatus)}</option>)}</select></label></div><LoadState loading={loading} error={error} empty={!loading && data?.items.length === 0} onRetry={() => void load()} />{!loading && data && data.items.length > 0 && <><div className="table-wrap"><table className="data-table data-table--stack"><thead><tr><th>Karşı taraf</th><th>Yön</th><th>Düzenleme / vade</th><th>Durum</th><th className="num">Toplam</th><th className="num">Kalan</th></tr></thead><tbody>{data.items.map((item) => <tr key={item.obligationId} className="finance-click-row" onClick={() => void open(item.obligationId)}><td data-label="Karşı taraf"><strong>{item.counterpartyName}</strong><small>{CATEGORY_LABELS[item.category]}</small></td><td data-label="Yön"><span className={`badge ${item.direction === 'Receivable' ? 'badge-success' : 'badge-danger'}`}>{item.direction === 'Receivable' ? 'Alacak' : 'Borç'}</span></td><td data-label="Düzenleme / vade">{date(item.issuedOn)}<small>Vade: {date(item.dueOn)}</small></td><td data-label="Durum"><span className={`badge ${obligationBadge(item.status)}`}>{obligationStatusLabel(item.status)}</span></td><td data-label="Toplam" className="num">{money(item.amount)}</td><td data-label="Kalan" className="num"><strong>{money(item.amount - item.settledAmount)}</strong></td></tr>)}</tbody></table></div><Pager page={data.page} totalPages={data.totalPages} totalCount={data.totalCount} onChange={setPage} /></>}{createOpen && <ObligationCreateModal onClose={() => setCreateOpen(false)} onSaved={() => void mutated('Alacak/borç kaydı oluşturuldu.', false)} />}{detail && <DetailDrawer title={detail.counterpartyName} subtitle={`${detail.direction === 'Receivable' ? 'Alacak' : 'Borç'} · ${obligationStatusLabel(detail.status)}`} onClose={() => setDetail(null)}><div className="stack finance-detail-stack"><DetailBlock title="Özet"><DetailRow label="Kategori" value={CATEGORY_LABELS[detail.category]} /><DetailRow label="Toplam" value={money(detail.amount)} /><DetailRow label="Tahsil/ödenen" value={money(detail.settledAmount)} /><DetailRow label="Kalan" value={money(detail.amount - detail.settledAmount)} /><DetailRow label="Düzenleme" value={date(detail.issuedOn)} /><DetailRow label="Vade" value={date(detail.dueOn)} />{detail.description && <p>{detail.description}</p>}</DetailBlock><DetailBlock title="Tahsilat / ödeme bağlantıları">{detail.settlements.length === 0 ? <p className="muted">Bağlı nakit işlemi yok.</p> : detail.settlements.map((item) => <div className="finance-settlement" key={item.settlementId}><div><strong>{money(item.amount)}</strong><small>{date(item.settledOn)} · {item.reference ?? 'Referans yok'}</small><span className="mono">İşlem {item.transactionId.slice(0, 8)}</span></div><button className="btn btn-danger-outline btn-sm" type="button" onClick={() => setSettlementToCancel(item.settlementId)}>Bağlantıyı iptal et</button></div>)}</DetailBlock></div><div className="finance-drawer-actions">{(detail.status === 'Open' || detail.status === 'PartiallySettled') && <button className="btn btn-primary" type="button" onClick={() => setAction('settle')}>{detail.direction === 'Receivable' ? 'Tahsilat kaydet' : 'Ödeme kaydet'}</button>}{(detail.status === 'Open' || detail.status === 'PartiallySettled') && <button className="btn btn-secondary" type="button" onClick={() => setAction('writeOff')}>{detail.direction === 'Receivable' ? 'Tahsil edilemez yaz' : 'Ödenmeyecek yaz'}</button>}{detail.status === 'Open' && detail.settledAmount === 0 && <button className="btn btn-danger-outline" type="button" onClick={() => setAction('cancel')}>Kaydı iptal et</button>}</div></DetailDrawer>}{action && detail && <ObligationActionModal action={action} detail={detail} accounts={accounts} onClose={() => setAction(null)} onSaved={(message) => void mutated(message)} />}{settlementToCancel && detail && <CancelSettlementModal obligationId={detail.obligationId} settlementId={settlementToCancel} onClose={() => setSettlementToCancel(null)} onSaved={() => void mutated('Settlement bağlantısı iptal edildi; nakit işlemi korundu.')} />}</section>;
}

function obligationStatusLabel(status: FinanceObligationStatus) { return ({ Open: 'Açık', PartiallySettled: 'Kısmen kapandı', Settled: 'Kapandı', WrittenOff: 'Kayıttan düşüldü', Cancelled: 'İptal' })[status]; }
function obligationBadge(status: FinanceObligationStatus) { return status === 'Settled' ? 'badge-success' : status === 'Open' || status === 'PartiallySettled' ? 'badge-warning' : status === 'WrittenOff' ? 'badge-danger' : 'badge-neutral'; }

function ObligationCreateModal({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
  const [direction, setDirection] = useState<FinanceObligationDirection>('Receivable'); const [category, setCategory] = useState<FinanceCategory>('LicenseSales'); const [counterparty, setCounterparty] = useState(''); const [description, setDescription] = useState(''); const [amountText, setAmountText] = useState(''); const [issuedOn, setIssuedOn] = useState(today()); const [dueOn, setDueOn] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const amount = parseMoney(amountText); const categories = direction === 'Receivable' ? INCOME_CATEGORIES : EXPENSE_CATEGORIES;
  useEffect(() => { if (!categories.includes(category)) setCategory(categories[0]); }, [direction, category, categories]);
  async function submit(event: FormEvent) { event.preventDefault(); if (amount === null) return; setBusy(true); setError(null); try { await createFinanceObligation({ direction, category, counterpartyName: counterparty.trim(), description: description.trim() || null, amount, issuedOn, dueOn: dueOn || null }); onSaved(); } catch (e) { setError(apiMessage(e, 'Kayıt oluşturulamadı.')); } finally { setBusy(false); } }
  const valid = !!counterparty.trim() && amount !== null && !!issuedOn && (!dueOn || dueOn >= issuedOn);
  return <Modal title="Yeni alacak veya borç" description="Bu kayıt tek başına nakit bakiyesini değiştirmez." onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><div className="finance-segmented"><button type="button" className={direction === 'Receivable' ? 'active' : ''} onClick={() => setDirection('Receivable')}>Alacak</button><button type="button" className={direction === 'Payable' ? 'active' : ''} onClick={() => setDirection('Payable')}>Borç</button></div><label>Karşı taraf<input className="text-input" value={counterparty} onChange={(e) => setCounterparty(e.target.value)} /></label><div className="finance-form-grid"><label>Kategori<select className="select-input" value={category} onChange={(e) => setCategory(e.target.value as FinanceCategory)}>{categories.map((x) => <option key={x} value={x}>{CATEGORY_LABELS[x]}</option>)}</select></label><label>Tutar (TRY)<input className="text-input mono" inputMode="decimal" value={amountText} onChange={(e) => setAmountText(e.target.value)} placeholder="0,00" /></label><label>Düzenleme tarihi<input className="text-input" type="date" value={issuedOn} onChange={(e) => setIssuedOn(e.target.value)} /></label><label>Vade<input className="text-input" type="date" value={dueOn} min={issuedOn} onChange={(e) => setDueOn(e.target.value)} /></label></div><label>Açıklama<textarea className="text-input" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Opsiyonel" /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={valid} onClose={onClose} submit="Kaydı oluştur" /></form></Modal>;
}

function ObligationActionModal({ action, detail, accounts, onClose, onSaved }: { action: 'settle' | 'writeOff' | 'cancel'; detail: FinanceObligationListItem; accounts: FinanceAccountListItem[]; onClose: () => void; onSaved: (message: string) => void }) {
  const remaining = detail.amount - detail.settledAmount; const [accountId, setAccountId] = useState(''); const [amountText, setAmountText] = useState(String(remaining)); const [on, setOn] = useState(today()); const [reference, setReference] = useState(''); const [reason, setReason] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const amount = parseMoney(amountText); const active = accounts.filter((x) => x.status === 'Active');
  const valid = action === 'settle' ? !!accountId && amount !== null && amount <= remaining && !!on : !!reason.trim() && !!on;
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { if (action === 'settle' && amount !== null) await settleFinanceObligation(detail.obligationId, { accountId, amount, settledOn: on, reference: reference.trim() || null }); else if (action === 'writeOff') await writeOffFinanceObligation(detail.obligationId, on, reason.trim()); else await cancelFinanceObligation(detail.obligationId, on, reason.trim()); onSaved(action === 'settle' ? `${detail.direction === 'Receivable' ? 'Tahsilat' : 'Ödeme'} kaydedildi.` : action === 'writeOff' ? 'Kalan yükümlülük kayıttan düşüldü.' : 'Yükümlülük iptal edildi.'); } catch (e) { setError(apiMessage(e, 'İşlem tamamlanamadı.')); } finally { setBusy(false); } }
  const title = action === 'settle' ? (detail.direction === 'Receivable' ? 'Tahsilat kaydet' : 'Ödeme kaydet') : action === 'writeOff' ? 'Kalan tutarı kayıttan düş' : 'Yükümlülüğü iptal et';
  return <Modal danger={action !== 'settle'} title={title} description={`${detail.counterpartyName} · kalan ${money(remaining)}`} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}>{action === 'settle' ? <><label>Hesap<select className="select-input" value={accountId} onChange={(e) => setAccountId(e.target.value)}><option value="">Hesap seçin</option>{active.map((x) => <option key={x.accountId} value={x.accountId}>{x.holderDisplayName} · {x.name} ({money(x.currentBalance)})</option>)}</select></label><div className="finance-form-grid"><label>Tutar<input className="text-input mono" value={amountText} onChange={(e) => setAmountText(e.target.value)} />{amount !== null && amount > remaining && <small className="field-error">Kalan tutar aşılamaz.</small>}</label><label>Tarih<input className="text-input" type="date" value={on} onChange={(e) => setOn(e.target.value)} /></label></div><label>Referans<input className="text-input" value={reference} onChange={(e) => setReference(e.target.value)} placeholder="Opsiyonel" /></label><Banner tone="info">Bu işlem ayrıca normal bir {detail.direction === 'Receivable' ? 'gelir' : 'gider'} kaydı oluşturur.</Banner></> : <><Banner tone="warning">Bu aksiyon yükümlülüğü kapatır ve denetim geçmişine yazılır.</Banner><label>Tarih<input className="text-input" type="date" value={on} onChange={(e) => setOn(e.target.value)} /></label><label>Zorunlu gerekçe<textarea className="text-input" value={reason} onChange={(e) => setReason(e.target.value)} /></label></>}{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={valid} onClose={onClose} submit={action === 'settle' ? 'Nakit işlemini kaydet' : 'Onayla'} danger={action !== 'settle'} /></form></Modal>;
}

function CancelSettlementModal({ obligationId, settlementId, onClose, onSaved }: { obligationId: string; settlementId: string; onClose: () => void; onSaved: () => void }) {
  const [reason, setReason] = useState(''); const [phrase, setPhrase] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { await cancelFinanceObligationSettlement(obligationId, settlementId, reason.trim()); onSaved(); } catch (e) { setError(apiMessage(e, 'Settlement bağlantısı iptal edilemedi.')); } finally { setBusy(false); } }
  return <Modal danger title="Settlement bağlantısını iptal et" description="Yükümlülüğün tahsil/ödenen tutarı azalır; gerçek nakit işlemi defterde kalır." onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><Banner tone="warning"><strong>Nakit işlemi silinmez.</strong> Yalnızca bu yükümlülükle kurulan attribution bağlantısı kaldırılır.</Banner><label>Gerekçe<textarea className="text-input" value={reason} onChange={(e) => setReason(e.target.value)} /></label><label>Onaylamak için <strong>BAĞLANTIYI KALDIR</strong> yazın<input className="text-input mono" value={phrase} onChange={(e) => setPhrase(e.target.value)} /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={!!reason.trim() && phrase === 'BAĞLANTIYI KALDIR'} onClose={onClose} submit="Bağlantıyı kaldır" danger /></form></Modal>;
}

function FinanceAccounts({ accounts, holders, loading, reload, onChanged }: { accounts: FinanceAccountListItem[]; holders: FinanceAccountHolderListItem[]; loading: boolean; reload: () => Promise<void>; onChanged: (message: string) => Promise<void> }) {
  const [asOfOn, setAsOfOn] = useState(today()); const [datedAccounts, setDatedAccounts] = useState<FinanceAccountListItem[] | null>(null); const [error, setError] = useState<string | null>(null);
  const [modal, setModal] = useState<'holder' | 'account' | null>(null); const [shareHolder, setShareHolder] = useState<FinanceAccountHolderListItem | null>(null); const [deactivateHolder, setDeactivateHolder] = useState<FinanceAccountHolderListItem | null>(null); const [closeAccount, setCloseAccount] = useState<FinanceAccountListItem | null>(null); const [openingAccount, setOpeningAccount] = useState<FinanceAccountListItem | null>(null);
  const visibleAccounts = datedAccounts ?? accounts; const totalShare = holders.filter((x) => x.status === 'Active').reduce((sum, x) => sum + x.shareBasisPoints, 0);
  async function loadDate() { setError(null); try { setDatedAccounts(await listFinanceAccounts(asOfOn)); } catch (e) { setError(apiMessage(e, 'Tarihli bakiyeler alınamadı.')); } }
  async function mutated(message: string) { setModal(null); setShareHolder(null); setDeactivateHolder(null); setCloseAccount(null); setOpeningAccount(null); setDatedAccounts(null); await reload(); await onChanged(message); }
  return <section className="finance-panel" role="tabpanel"><div className="finance-section-head"><div><span className="eyebrow">Varlık yapısı</span><h2>Hesaplar ve ortaklar</h2><p>Bakiyeler defter hareketlerinden seçilen tarih itibarıyla türetilir; saklanan bakiye alanı yoktur.</p></div><div className="cluster finance-actions"><button className="btn btn-secondary" onClick={() => setModal('holder')}>+ Hesap sahibi</button><button className="btn btn-primary" disabled={!holders.some((x) => x.status === 'Active')} onClick={() => setModal('account')}>+ Hesap aç</button></div></div><div className={`finance-share-banner ${totalShare === 10000 ? 'ready' : 'warning'}`}><div><span>Aktif ortak payı</span><strong>{percent(totalShare)}%</strong></div><p>{totalShare === 10000 ? 'Kâr dağıtımı için pay toplamı hazır.' : `Dağıtıma hazır olmak için toplam %100 olmalı; fark ${percent(Math.abs(10000 - totalShare))} puan.`}</p></div><div className="finance-subsection-head"><div><h3>Hesaplar</h3><p>Negatif bakiyeler görünür; yalnız transfer ve dağıtım kaynak yeterliliği kontrol eder.</p></div><div className="cluster"><label className="finance-inline-label">Bakiye tarihi<input className="text-input" type="date" value={asOfOn} onChange={(e) => setAsOfOn(e.target.value)} /></label><button className="btn btn-secondary btn-sm" type="button" onClick={() => void loadDate()}>Getir</button></div></div>{error && <div className="error">{error}</div>}<LoadState loading={loading} empty={!loading && visibleAccounts.length === 0} />{visibleAccounts.length > 0 && <div className="finance-account-grid">{visibleAccounts.map((item) => <article className={`finance-account-card${item.currentBalance < 0 ? ' is-negative' : ''}`} key={item.accountId}><div className="finance-account-card__top"><span className="finance-account-icon">{item.kind === 'Bank' ? '▤' : '₺'}</span><span className={`badge ${item.status === 'Active' ? 'badge-success' : 'badge-neutral'}`}>{item.status === 'Active' ? 'Aktif' : 'Kapalı'}</span></div><h3>{item.name}</h3><p>{item.holderDisplayName} · {item.kind === 'Bank' ? 'Banka' : 'Kasa'}</p><strong className={item.currentBalance < 0 ? 'negative' : ''}>{money(item.currentBalance)}</strong><small>{date(item.balanceAsOfOn)} itibarıyla</small>{item.currentBalance < 0 && <div className="finance-overdraft">Eksi bakiye</div>}<div className="finance-account-actions">{item.status === 'Active' && <button className="btn btn-tertiary btn-sm" onClick={() => setOpeningAccount(item)}>Açılış kaydı</button>}{item.status === 'Active' && <button className="btn btn-danger-outline btn-sm" onClick={() => setCloseAccount(item)}>Hesabı kapat</button>}</div></article>)}</div>}<div className="finance-subsection-head"><div><h3>Hesap sahipleri ve ortak payları</h3><p>Paylar arayüzde yüzde, backend’de 10.000 baz puan üzerinden tutulur.</p></div></div><div className="table-wrap"><table className="data-table data-table--stack"><thead><tr><th>Hesap sahibi</th><th>Bağlı kullanıcı</th><th>Durum</th><th>Ortak payı</th><th>İşlem</th></tr></thead><tbody>{holders.map((item) => <tr key={item.holderId}><td data-label="Hesap sahibi"><strong>{item.displayName}</strong></td><td data-label="Bağlı kullanıcı" className="mono">{item.userId ?? '—'}</td><td data-label="Durum"><span className={`badge ${item.status === 'Active' ? 'badge-success' : 'badge-neutral'}`}>{item.status === 'Active' ? 'Aktif' : 'Pasif'}</span></td><td data-label="Ortak payı"><strong>%{percent(item.shareBasisPoints)}</strong></td><td data-label="İşlem"><div className="cluster finance-row-actions">{item.status === 'Active' && <button className="btn btn-secondary btn-sm" onClick={() => setShareHolder(item)}>Payı düzenle</button>}{item.status === 'Active' && <button className="btn btn-danger-outline btn-sm" onClick={() => setDeactivateHolder(item)}>Pasifleştir</button>}</div></td></tr>)}</tbody></table></div>{modal === 'holder' && <HolderCreateModal onClose={() => setModal(null)} onSaved={() => void mutated('Hesap sahibi oluşturuldu.')} />}{modal === 'account' && <AccountCreateModal holders={holders} onClose={() => setModal(null)} onSaved={() => void mutated('Finans hesabı açıldı.')} />}{shareHolder && <HolderShareModal holder={shareHolder} onClose={() => setShareHolder(null)} onSaved={() => void mutated('Ortak payı güncellendi.')} />}{deactivateHolder && <HolderDeactivateModal holder={deactivateHolder} onClose={() => setDeactivateHolder(null)} onSaved={() => void mutated('Hesap sahibi pasifleştirildi ve payı sıfırlandı.')} />}{closeAccount && <AccountCloseModal account={closeAccount} onClose={() => setCloseAccount(null)} onSaved={() => void mutated('Finans hesabı kapatıldı.')} />}{openingAccount && <OpeningBalanceModal account={openingAccount} onClose={() => setOpeningAccount(null)} onSaved={() => void mutated('Açılış bakiyesi kaydedildi.')} />}</section>;
}

function HolderCreateModal({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) { const [name, setName] = useState(''); const [userId, setUserId] = useState(''); const [share, setShare] = useState('0'); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const shareValue = parseMoney(share, { positive: false }); const valid = !!name.trim() && shareValue !== null && shareValue >= 0 && shareValue <= 100; async function submit(e: FormEvent) { e.preventDefault(); if (!valid || shareValue === null) return; setBusy(true); try { await createFinanceHolder({ displayName: name.trim(), userId: userId.trim() || null, shareBasisPoints: Math.round(shareValue * 100) }); onSaved(); } catch (err) { setError(apiMessage(err, 'Hesap sahibi oluşturulamadı.')); } finally { setBusy(false); } } return <Modal title="Hesap sahibi oluştur" description="Bir kişi, şirket, kasa sorumlusu veya ortak tanımlayın." onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><label>Görünen ad<input className="text-input" value={name} onChange={(e) => setName(e.target.value)} /></label><label>Bağlı kullanıcı kimliği<input className="text-input mono" value={userId} onChange={(e) => setUserId(e.target.value)} placeholder="Opsiyonel UUID" /></label><label>Ortak payı (%)<input className="text-input mono" inputMode="decimal" value={share} onChange={(e) => setShare(e.target.value)} /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={valid} onClose={onClose} submit="Oluştur" /></form></Modal>; }

function AccountCreateModal({ holders, onClose, onSaved }: { holders: FinanceAccountHolderListItem[]; onClose: () => void; onSaved: () => void }) { const active = holders.filter((x) => x.status === 'Active'); const [holderId, setHolderId] = useState(''); const [name, setName] = useState(''); const [kind, setKind] = useState<FinanceAccountKind>('Bank'); const [openedOn, setOpenedOn] = useState(today()); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); try { await openFinanceAccount({ financeAccountHolderId: holderId, name: name.trim(), kind, openedOn }); onSaved(); } catch (err) { setError(apiMessage(err, 'Hesap açılamadı.')); } finally { setBusy(false); } } return <Modal title="Finans hesabı aç" description="Kasa veya banka hesabı oluşturun; ilk tutarı daha sonra açılış kaydıyla girin." onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><label>Hesap sahibi<select className="select-input" value={holderId} onChange={(e) => setHolderId(e.target.value)}><option value="">Seçin</option>{active.map((x) => <option key={x.holderId} value={x.holderId}>{x.displayName}</option>)}</select></label><div className="finance-form-grid"><label>Hesap adı<input className="text-input" value={name} onChange={(e) => setName(e.target.value)} /></label><label>Tür<select className="select-input" value={kind} onChange={(e) => setKind(e.target.value as FinanceAccountKind)}><option value="Bank">Banka</option><option value="Cash">Kasa</option></select></label><label>Açılış tarihi<input className="text-input" type="date" value={openedOn} onChange={(e) => setOpenedOn(e.target.value)} /></label></div>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={!!holderId && !!name.trim() && !!openedOn} onClose={onClose} submit="Hesabı aç" /></form></Modal>; }

function HolderShareModal({ holder, onClose, onSaved }: { holder: FinanceAccountHolderListItem; onClose: () => void; onSaved: () => void }) { const [share, setShare] = useState(percent(holder.shareBasisPoints)); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const value = parseMoney(share, { positive: false }); async function submit(e: FormEvent) { e.preventDefault(); if (value === null) return; setBusy(true); try { await setFinanceHolderShare(holder.holderId, Math.round(value * 100)); onSaved(); } catch (err) { setError(apiMessage(err, 'Pay güncellenemedi.')); } finally { setBusy(false); } } return <Modal title="Ortak payını düzenle" description={holder.displayName} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><label>Pay (%)<input className="text-input mono" inputMode="decimal" value={share} onChange={(e) => setShare(e.target.value)} /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={value !== null && value >= 0 && value <= 100} onClose={onClose} submit="Payı kaydet" /></form></Modal>; }

function HolderDeactivateModal({ holder, onClose, onSaved }: { holder: FinanceAccountHolderListItem; onClose: () => void; onSaved: () => void }) { const [phrase, setPhrase] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); try { await deactivateFinanceHolder(holder.holderId); onSaved(); } catch (err) { setError(apiMessage(err, 'Hesap sahibi pasifleştirilemedi.')); } finally { setBusy(false); } } return <Modal danger title="Hesap sahibini pasifleştir" description={`${holder.displayName} dağıtım dışında kalacak ve payı sıfırlanacak.`} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><label>Onaylamak için <strong>PASİF</strong> yazın<input className="text-input mono" value={phrase} onChange={(e) => setPhrase(e.target.value)} /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={phrase === 'PASİF'} onClose={onClose} submit="Pasifleştir" danger /></form></Modal>; }

function AccountCloseModal({ account, onClose, onSaved }: { account: FinanceAccountListItem; onClose: () => void; onSaved: () => void }) { const [reason, setReason] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); try { await closeFinanceAccount(account.accountId, reason.trim()); onSaved(); } catch (err) { setError(apiMessage(err, 'Hesap kapatılamadı.')); } finally { setBusy(false); } } return <Modal danger title="Finans hesabını kapat" description={`${account.name} yeni hareket kabul etmeyecek; geçmiş korunacak.`} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><DetailRow label="Güncel bakiye" value={money(account.currentBalance)} /><label>Zorunlu gerekçe<textarea className="text-input" value={reason} onChange={(e) => setReason(e.target.value)} /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={!!reason.trim()} onClose={onClose} submit="Hesabı kapat" danger /></form></Modal>; }

function OpeningBalanceModal({ account, onClose, onSaved }: { account: FinanceAccountListItem; onClose: () => void; onSaved: () => void }) { const [amountText, setAmountText] = useState(''); const [on, setOn] = useState(account.openedOn); const [description, setDescription] = useState('Açılış bakiyesi'); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const amount = parseMoney(amountText, { positive: false }); async function submit(e: FormEvent) { e.preventDefault(); if (amount === null) return; setBusy(true); try { await recordFinanceOpeningBalance({ accountId: account.accountId, signedAmount: amount, occurredOn: on, description: description.trim() }); onSaved(); } catch (err) { setError(apiMessage(err, 'Açılış bakiyesi kaydedilemedi.')); } finally { setBusy(false); } } return <Modal title="Açılış bakiyesi kaydet" description={`${account.holderDisplayName} · ${account.name}`} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><Banner tone="warning">Açılış bakiyesi sonradan düzenlenemez veya silinemez.</Banner><div className="finance-form-grid"><label>İmzalı tutar<input className="text-input mono" value={amountText} onChange={(e) => setAmountText(e.target.value)} placeholder="-500,00 veya 500,00" /></label><label>Tarih<input className="text-input" type="date" value={on} onChange={(e) => setOn(e.target.value)} /></label></div><label>Açıklama<input className="text-input" value={description} onChange={(e) => setDescription(e.target.value)} /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={amount !== null && !!on && !!description.trim()} onClose={onClose} submit="Açılışı kaydet" /></form></Modal>; }

function FinanceDistributions({ accounts, onChanged }: { accounts: FinanceAccountListItem[]; onChanged: (message: string) => Promise<void> }) {
  const now = new Date(); const monthStart = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`; const previousMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0); const defaultEnd = `${previousMonthEnd.getFullYear()}-${String(previousMonthEnd.getMonth() + 1).padStart(2, '0')}-${String(previousMonthEnd.getDate()).padStart(2, '0')}`; const previousStart = `${previousMonthEnd.getFullYear()}-${String(previousMonthEnd.getMonth() + 1).padStart(2, '0')}-01`;
  const [startOn, setStartOn] = useState(previousStart || monthStart); const [endOn, setEndOn] = useState(defaultEnd); const [accountId, setAccountId] = useState(''); const [plan, setPlan] = useState<FinanceDistributionPlan | null>(null); const [history, setHistory] = useState<FinanceDistributionListItem[]>([]); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const [confirmOpen, setConfirmOpen] = useState(false); const [reverseItem, setReverseItem] = useState<FinanceDistributionListItem | null>(null);
  const load = useCallback(async () => { setLoading(true); setError(null); try { setHistory(await listFinanceDistributions()); } catch (e) { setError(apiMessage(e, 'Dağıtım geçmişi alınamadı.')); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function preview() { setBusy(true); setError(null); setPlan(null); try { setPlan(await previewFinanceDistribution({ periodStartOn: startOn, periodEndOn: endOn, sourceAccountId: accountId })); } catch (e) { setError(apiMessage(e, 'Dağıtım ön izlemesi oluşturulamadı.')); } finally { setBusy(false); } }
  async function mutated(message: string) { setConfirmOpen(false); setReverseItem(null); setPlan(null); await load(); await onChanged(message); }
  const activeAccounts = accounts.filter((x) => x.status === 'Active');
  return <section className="finance-panel" role="tabpanel"><div className="finance-section-head"><div><span className="eyebrow">Bağlayıcı ön izleme</span><h2>Kâr dağıtımı</h2><p>Plan sunucuda hesaplanır; onay anında aynı hash yeniden doğrulanır ve dönem yalnızca bir kez dağıtılabilir.</p></div></div><div className="finance-distribution-layout"><article className="finance-distribution-builder"><ol className="finance-steps"><li className="done"><span>1</span>Kapsam</li><li className={plan ? 'done' : 'active'}><span>2</span>Ön izleme</li><li className={plan?.outcome === 'Ready' ? 'active' : ''}><span>3</span>Güçlü onay</li></ol><div className="finance-form"><div className="finance-form-grid"><label>Dönem başlangıcı<input className="text-input" type="date" value={startOn} onChange={(e) => { setStartOn(e.target.value); setPlan(null); }} /></label><label>Dönem bitişi<input className="text-input" type="date" value={endOn} onChange={(e) => { setEndOn(e.target.value); setPlan(null); }} /></label></div><label>Kaynak hesap<select className="select-input" value={accountId} onChange={(e) => { setAccountId(e.target.value); setPlan(null); }}><option value="">Hesap seçin</option>{activeAccounts.map((x) => <option key={x.accountId} value={x.accountId}>{x.holderDisplayName} · {x.name} ({money(x.currentBalance)})</option>)}</select></label><button className="btn btn-primary" type="button" disabled={busy || !accountId || !startOn || !endOn || endOn < startOn} onClick={() => void preview()}>{busy ? 'Hesaplanıyor…' : 'Sunucuda ön izle'}</button>{error && <div className="error">{error}</div>}</div>{plan && <DistributionPreview plan={plan} onConfirm={() => setConfirmOpen(true)} />}</article><article className="finance-distribution-note"><span className="finance-shield">✓</span><h3>Dağıtım güvenlikleri</h3><ul><li>Paylar 10.000 baz puan olmalı.</li><li>Tutar istemcide hesaplanmaz.</li><li>Plan hash’i onay anında yeniden doğrulanır.</li><li>Confirmation token tekrarlı isteği idempotent yapar.</li><li>Tersine çevirme silmez; telafi eden nakit girişleri oluşturur.</li></ul></article></div><div className="finance-subsection-head"><div><h3>Dağıtım geçmişi</h3><p>Çalıştırılan ve tersine çevrilen dönemler.</p></div></div><LoadState loading={loading} error={error} empty={!loading && history.length === 0} onRetry={() => void load()} />{history.length > 0 && <div className="table-wrap"><table className="data-table data-table--stack"><thead><tr><th>Dönem</th><th>Çalıştırma</th><th>Durum</th><th>Kaynak hesap</th><th className="num">Tutar</th><th>İşlem</th></tr></thead><tbody>{history.map((item) => <tr key={item.distributionId}><td data-label="Dönem">{date(item.periodStartOn)} – {date(item.periodEndOn)}</td><td data-label="Çalıştırma">{formatDateTime(item.executedAtUtc)}</td><td data-label="Durum"><span className={`badge ${item.status === 'Executed' ? 'badge-success' : 'badge-neutral'}`}>{item.status === 'Executed' ? 'Çalıştırıldı' : 'Tersine çevrildi'}</span></td><td data-label="Kaynak hesap" className="mono">{accounts.find((x) => x.accountId === item.sourceFinanceAccountId)?.name ?? item.sourceFinanceAccountId.slice(0, 8)}</td><td data-label="Tutar" className="num">{money(item.distributableAmount)}</td><td data-label="İşlem">{item.status === 'Executed' && <button className="btn btn-danger-outline btn-sm" onClick={() => setReverseItem(item)}>Tersine çevir</button>}</td></tr>)}</tbody></table></div>}{confirmOpen && plan && <DistributionConfirmModal plan={plan} onClose={() => setConfirmOpen(false)} onSaved={() => void mutated('Kâr dağıtımı çalıştırıldı.')} />}{reverseItem && <DistributionReverseModal item={reverseItem} onClose={() => setReverseItem(null)} onSaved={() => void mutated('Dağıtım telafi işlemleriyle tersine çevrildi.')} />}</section>;
}

function DistributionPreview({ plan, onConfirm }: { plan: FinanceDistributionPlan; onConfirm: () => void }) {
  if (plan.outcome !== 'Ready') { const messages: Record<string, string> = { NothingToDistribute: 'Bu dönemde dağıtılabilir pozitif kâr yok.', NoEligiblePartners: 'Dağıtıma uygun aktif ortak bulunmuyor.', SharesDoNotSumToTotal: 'Aktif ortak paylarının toplamı %100 değil.', AlreadyDistributedForPeriod: 'Bu dönem daha önce dağıtılmış.', SourceAccountClosed: 'Kaynak hesap kapalı.', SourceAccountNotFound: 'Kaynak hesap bulunamadı.' }; return <Banner tone="warning"><strong>Plan hazır değil.</strong> {messages[plan.outcome] ?? plan.outcome}</Banner>; }
  return <div className="finance-plan"><div className="finance-plan-total"><span>Dağıtılabilir net kâr</span><strong>{money(plan.distributableAmount)}</strong><small>{date(plan.periodStartOn)} – {date(plan.periodEndOn)}</small></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Ortak</th><th>Pay</th><th className="num">Tahsis</th></tr></thead><tbody>{plan.shares.map((share) => <tr key={share.holderId}><td>{share.holderDisplayName}{share.remainderUnitAwarded && <small> · kuruş farkı tahsis edildi</small>}</td><td>%{percent(share.shareBasisPoints)}</td><td className="num"><strong>{money(share.allocatedAmount)}</strong></td></tr>)}</tbody></table></div>{plan.exclusions.length > 0 && <details><summary>{plan.exclusions.length} hesap sahibi dağıtım dışında</summary><ul>{plan.exclusions.map((x) => <li key={x.holderId}>{x.holderDisplayName} · {x.reason}</li>)}</ul></details>}<button className="btn btn-danger btn-block" type="button" onClick={onConfirm}>Güçlü onaya geç</button></div>;
}

function DistributionConfirmModal({ plan, onClose, onSaved }: { plan: FinanceDistributionPlan; onClose: () => void; onSaved: () => void }) { const [phrase, setPhrase] = useState(''); const [reason, setReason] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const expected = plan.expectedConfirmationPhrase ?? ''; const valid = phrase === expected && !!reason.trim() && !!plan.confirmationToken && !!plan.planHash && !!plan.sourceAccountId; async function submit(e: FormEvent) { e.preventDefault(); if (!valid) return; setBusy(true); setError(null); try { await executeFinanceDistribution({ periodStartOn: plan.periodStartOn, periodEndOn: plan.periodEndOn, sourceAccountId: plan.sourceAccountId!, confirmationToken: plan.confirmationToken!, planHash: plan.planHash!, expectedConfirmationPhrase: expected, reason: reason.trim() }); onSaved(); } catch (err) { setError(apiMessage(err, 'Dağıtım çalıştırılamadı. Ön izlemeyi yenileyip tekrar deneyin.')); } finally { setBusy(false); } } return <Modal danger title={`${money(plan.distributableAmount)} dağıtılacak`} description={`${plan.shares.length} ortak · ${date(plan.periodStartOn)} – ${date(plan.periodEndOn)}`} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><Banner tone="danger"><strong>Bu işlem geri alınamaz biçimde kaydedilir.</strong> Düzeltme gerekirse ayrı bir tersine çevirme işlemi oluşturulur.</Banner><label>Dağıtım gerekçesi<textarea className="text-input" value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Zorunlu denetim gerekçesi" /></label><label>Onaylamak için tutarı tam olarak yazın: <strong className="mono">{expected}</strong><input className="text-input mono" inputMode="decimal" value={phrase} onChange={(e) => setPhrase(e.target.value)} autoComplete="off" /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={valid} onClose={onClose} submit="Dağıtımı çalıştır" danger /></form></Modal>; }

function DistributionReverseModal({ item, onClose, onSaved }: { item: FinanceDistributionListItem; onClose: () => void; onSaved: () => void }) { const [reason, setReason] = useState(''); const [phrase, setPhrase] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setError(null); try { await reverseFinanceDistribution(item.distributionId, reason.trim()); onSaved(); } catch (err) { setError(apiMessage(err, 'Dağıtım tersine çevrilemedi.')); } finally { setBusy(false); } } return <Modal danger title="Dağıtımı tersine çevir" description={`${money(item.distributableAmount)} için telafi eden nakit girişleri oluşturulacak.`} onClose={onClose}><form className="finance-form" onSubmit={(e) => void submit(e)}><Banner tone="warning">Geçmiş dağıtım silinmez; durumu “Tersine çevrildi” olur.</Banner><label>Zorunlu gerekçe<textarea className="text-input" value={reason} onChange={(e) => setReason(e.target.value)} /></label><label>Onaylamak için <strong>TERSİNE ÇEVİR</strong> yazın<input className="text-input mono" value={phrase} onChange={(e) => setPhrase(e.target.value)} /></label>{error && <div className="error">{error}</div>}<FormActions busy={busy} valid={!!reason.trim() && phrase === 'TERSİNE ÇEVİR'} onClose={onClose} submit="Telafi işlemlerini oluştur" danger /></form></Modal>; }

function FinanceAudit() {
  const [action, setAction] = useState<FinanceAuditAction | ''>(''); const [subjectType, setSubjectType] = useState(''); const [actorUserId, setActorUserId] = useState(''); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [page, setPage] = useState(1); const [data, setData] = useState<PagedResult<FinanceAuditListItem> | null>(null); const [selected, setSelected] = useState<FinanceAuditDetail | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { setLoading(true); setError(null); try { setData(await listFinanceAudit({ action: action || undefined, subjectType: subjectType || undefined, actorUserId: actorUserId.trim() || undefined, from: from ? new Date(from).toISOString() : undefined, to: to ? new Date(to).toISOString() : undefined, page, pageSize: 50 })); } catch (e) { setError(apiMessage(e, 'Denetim kayıtları alınamadı.')); } finally { setLoading(false); } }, [action, subjectType, actorUserId, from, to, page]);
  useEffect(() => { void load(); }, [load]);
  async function open(item: FinanceAuditListItem) { setError(null); if (item.subjectType === 'FinanceTransaction') { try { const chain = await getFinanceTransactionHistory(item.subjectId); setSelected(chain.find((x) => x.summary.sequence === item.sequence) ?? { summary: item }); } catch (e) { setError(apiMessage(e, 'Denetim detayı alınamadı.')); } } else setSelected({ summary: item }); }
  return <section className="finance-panel" role="tabpanel"><div className="finance-section-head"><div><span className="eyebrow">Append-only kayıt</span><h2>Denetim geçmişi</h2><p>Finans modülündeki her önemli değişiklik aktör, gerekçe, tutar farkı ve correlation kimliğiyle izlenir.</p></div></div><div className="finance-filter-grid"><label>Aksiyon<select className="select-input" value={action} onChange={(e) => { setAction(e.target.value as FinanceAuditAction | ''); setPage(1); }}><option value="">Tüm aksiyonlar</option>{AUDIT_ACTIONS.map((x) => <option key={x} value={x}>{auditActionLabel(x)}</option>)}</select></label><label>Konu<select className="select-input" value={subjectType} onChange={(e) => { setSubjectType(e.target.value); setPage(1); }}><option value="">Tüm konular</option><option value="FinanceTransaction">İşlem</option><option value="FinanceObligation">Alacak/borç</option><option value="FinanceAccount">Hesap</option><option value="FinanceAccountHolder">Hesap sahibi</option><option value="FinanceDistribution">Dağıtım</option></select></label><label>Aktör kullanıcı UUID<input className="text-input mono" value={actorUserId} onChange={(e) => { setActorUserId(e.target.value); setPage(1); }} placeholder="Opsiyonel" /></label><label>Başlangıç<input className="text-input" type="datetime-local" value={from} onChange={(e) => { setFrom(e.target.value); setPage(1); }} /></label><label>Bitiş<input className="text-input" type="datetime-local" value={to} onChange={(e) => { setTo(e.target.value); setPage(1); }} /></label></div><LoadState loading={loading} error={error} empty={!loading && data?.items.length === 0} onRetry={() => void load()} />{!loading && data && data.items.length > 0 && <><div className="table-wrap"><table className="data-table data-table--stack"><thead><tr><th>Sıra / zaman</th><th>Aksiyon</th><th>Konu</th><th>Aktör</th><th>Değişen alanlar</th><th className="num">Tutar farkı</th></tr></thead><tbody>{data.items.map((item) => <tr key={item.sequence} className="finance-click-row" onClick={() => void open(item)}><td data-label="Sıra / zaman"><strong>#{item.sequence}</strong><small>{formatDateTime(item.occurredAtUtc)}</small></td><td data-label="Aksiyon"><span className={`badge ${auditBadge(item.action)}`}>{auditActionLabel(item.action)}</span></td><td data-label="Konu">{subjectLabel(item.subjectType)}<small className="mono">{item.subjectId.slice(0, 8)}</small></td><td data-label="Aktör">{item.actorEmail}</td><td data-label="Değişen alanlar">{item.changedFields.length ? item.changedFields.join(', ') : '—'}</td><td data-label="Tutar farkı" className={`num ${item.amountDelta > 0 ? 'positive' : item.amountDelta < 0 ? 'negative' : ''}`}>{money(item.amountDelta)}</td></tr>)}</tbody></table></div><Pager page={data.page} totalPages={data.totalPages} totalCount={data.totalCount} onChange={setPage} /></>}{selected && <DetailDrawer title={auditActionLabel(selected.summary.action)} subtitle={`#${selected.summary.sequence} · ${formatDateTime(selected.summary.occurredAtUtc)}`} onClose={() => setSelected(null)}><AuditChange detail={selected} expanded /></DetailDrawer>}</section>;
}

const AUDIT_ACTIONS: FinanceAuditAction[] = ['AccountOpened','AccountUpdated','AccountClosed','HolderCreated','HolderUpdated','HolderDeactivated','PartnerSharesChanged','TransactionCreated','TransactionUpdated','TransactionDeleted','ObligationCreated','ObligationUpdated','ObligationSettled','ObligationSettlementCancelled','ObligationWrittenOff','ObligationCancelled','DistributionExecuted','DistributionReversed'];
function auditActionLabel(action: FinanceAuditAction) { const words: Record<FinanceAuditAction, string> = { AccountOpened: 'Hesap açıldı', AccountUpdated: 'Hesap güncellendi', AccountClosed: 'Hesap kapatıldı', HolderCreated: 'Hesap sahibi oluşturuldu', HolderUpdated: 'Hesap sahibi güncellendi', HolderDeactivated: 'Hesap sahibi pasifleştirildi', PartnerSharesChanged: 'Ortak payları değişti', TransactionCreated: 'İşlem oluşturuldu', TransactionUpdated: 'İşlem güncellendi', TransactionDeleted: 'İşlem silindi', ObligationCreated: 'Yükümlülük oluşturuldu', ObligationUpdated: 'Yükümlülük güncellendi', ObligationSettled: 'Yükümlülük kapatıldı', ObligationSettlementCancelled: 'Settlement iptal edildi', ObligationWrittenOff: 'Kayıttan düşüldü', ObligationCancelled: 'Yükümlülük iptal edildi', DistributionExecuted: 'Dağıtım çalıştırıldı', DistributionReversed: 'Dağıtım tersine çevrildi' }; return words[action] ?? action; }
function auditBadge(action: FinanceAuditAction) { return action.includes('Deleted') || action.includes('Closed') || action.includes('Cancelled') || action.includes('WrittenOff') || action.includes('Reversed') ? 'badge-danger' : action.includes('Updated') || action.includes('Changed') ? 'badge-warning' : 'badge-success'; }
function subjectLabel(subject: string) { return ({ FinanceTransaction: 'İşlem', FinanceObligation: 'Alacak/borç', FinanceAccount: 'Hesap', FinanceAccountHolder: 'Hesap sahibi', FinanceDistribution: 'Dağıtım' } as Record<string, string>)[subject] ?? subject; }

function DetailBlock({ title, children }: { title: string; children: ReactNode }) { return <section className="finance-detail-block"><h3>{title}</h3><div>{children}</div></section>; }
function DetailRow({ label, value }: { label: string; value: string }) { return <div className="summary-row"><span className="muted">{label}</span><strong>{value}</strong></div>; }

function parseSnapshot(value?: string | null): Record<string, unknown> | null { if (!value) return null; try { return JSON.parse(value) as Record<string, unknown>; } catch { return null; } }
function displaySnapshotValue(value: unknown): string { if (value === null || value === undefined || value === '') return '—'; if (typeof value === 'object') return JSON.stringify(value); return String(value); }
function AuditChange({ detail, expanded = false }: { detail: FinanceAuditDetail; expanded?: boolean }) { const before = parseSnapshot(detail.beforeState); const after = parseSnapshot(detail.afterState); const keys = Array.from(new Set([...Object.keys(before ?? {}), ...Object.keys(after ?? {})])).filter((key) => displaySnapshotValue(before?.[key]) !== displaySnapshotValue(after?.[key])); const body = <><DetailRow label="Aktör" value={detail.summary.actorEmail} /><DetailRow label="Tutar farkı" value={money(detail.summary.amountDelta)} /><DetailRow label="Revizyon" value={String(detail.summary.revisionNumber)} /><DetailRow label="Correlation ID" value={detail.summary.correlationId ?? '—'} />{detail.summary.reason && <div className="finance-audit-reason"><span>Gerekçe</span><p>{detail.summary.reason}</p></div>}{keys.length > 0 && <div className="finance-diff"><div className="finance-diff__head"><span>Alan</span><span>Önce</span><span>Sonra</span></div>{keys.map((key) => <div key={key}><strong>{key}</strong><span>{displaySnapshotValue(before?.[key])}</span><span>{displaySnapshotValue(after?.[key])}</span></div>)}</div>}</>; return expanded ? <div className="stack finance-detail-stack">{body}</div> : <details className="finance-audit-item"><summary><span>{auditActionLabel(detail.summary.action)}</span><small>{formatDateTime(detail.summary.occurredAtUtc)} · {detail.summary.actorEmail}</small></summary><div>{body}</div></details>; }
